<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { adminApi } from '@/api';
import { useToast } from '@/stores/toast';
import { buildItemPayload } from '@/utils/inventoryItem';
import { paginateWarehouseItems } from '@/utils/inventoryOperations';

const router = useRouter();
const toast = useToast();
const items = ref([]);
const loading = ref(true);
const error = ref('');
const search = ref('');
const status = ref('ACTIVE');
const editing = ref(null);
const saving = ref(false);
const form = ref(blank());
const PAGE_SIZE = 10;
const ingredientPage = ref(1);

function blank() { return { inventoryCode: '', name: '', itemType: 'INGREDIENT', baseUnit: 'G', minimumQuantity: '0', countFrequency: 'DAILY', active: true }; }
const activeIngredients = computed(() => items.value.filter(item => item.itemType === 'INGREDIENT' && item.active !== false));
const ingredientsNeedingCost = computed(() => activeIngredients.value.filter(item => Number(item.averageUnitCost) <= 0));
const ingredientsNeedingStock = computed(() => activeIngredients.value.filter(item => Number(item.availableQuantity) <= Number(item.minimumQuantity)));
const ingredients = computed(() => items.value.filter(item => item.itemType === 'INGREDIENT').filter(item => status.value === 'ALL' || (status.value === 'ACTIVE') === (item.active !== false)).filter(item => `${item.name} ${item.inventoryCode}`.toLocaleLowerCase('vi').includes(search.value.trim().toLocaleLowerCase('vi'))));
const paginatedIngredients = computed(() => paginateWarehouseItems(ingredients.value, ingredientPage.value, PAGE_SIZE));
const unit = value => ({ G: 'g', ML: 'ml', PIECE: 'cái' }[value] || value);
const money = value => Number(value || 0).toLocaleString('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 });
async function load() { loading.value = true; error.value = ''; try { const data = await adminApi.getInventoryItems(); items.value = Array.isArray(data) ? data : []; } catch (e) { error.value = e.message || 'Không thể tải nguyên liệu'; } finally { loading.value = false; } }
function create() { editing.value = { mode: 'create' }; form.value = blank(); }
function edit(item) { editing.value = item; form.value = { inventoryCode: item.inventoryCode, name: item.name, itemType: 'INGREDIENT', baseUnit: item.baseUnit, minimumQuantity: String(item.minimumQuantity), countFrequency: 'DAILY', active: item.active !== false }; }
async function save() { if (!form.value.name.trim() || !/^[A-Z0-9-]{1,30}$/.test(form.value.inventoryCode.trim().toUpperCase())) { error.value = 'Nhập tên và mã nguyên liệu hợp lệ'; return; } saving.value = true; error.value = ''; try { const payload = buildItemPayload(form.value); if (editing.value.mode === 'create') await adminApi.createInventoryItem(payload); else await adminApi.updateInventoryItem(editing.value.inventoryItemId, payload); toast.success(editing.value.mode === 'create' ? 'Đã thêm nguyên liệu' : 'Đã lưu nguyên liệu'); editing.value = null; await load(); } catch (e) { error.value = e.message || 'Không thể lưu nguyên liệu'; } finally { saving.value = false; } }
watch([search, status], () => { ingredientPage.value = 1; });
watch(() => paginatedIngredients.value.page, page => { if (ingredientPage.value !== page) ingredientPage.value = page; });
onMounted(load);
</script>

<template>
  <main class="ingredients-page">
    <header class="page-header"><div><p class="eyebrow">Kho · Dữ liệu nền</p><h1>Nguyên liệu</h1><p>Quản lý danh mục dùng chung cho nhập hàng, công thức và kiểm kê.</p></div><button class="btn btn-primary" @click="create">Thêm nguyên liệu</button></header>
    <section class="command-rail ingredient-command-rail" aria-label="Tình trạng dữ liệu nguyên liệu">
      <button class="command-card command-attention ingredients-needing-cost" @click="router.push({ name: 'AdminGoodsReceipts' })"><span>Cần hoàn thiện</span><strong>{{ ingredientsNeedingCost.length }} nguyên liệu</strong><small>Chưa có giá vốn · Nhập hàng để cập nhật</small></button>
      <article class="command-card"><span>Đang sử dụng</span><strong>{{ activeIngredients.length }}</strong><small>Danh mục nguyên liệu hoạt động</small></article>
      <article class="command-card"><span>Cần nhập thêm</span><strong>{{ ingredientsNeedingStock.length }}</strong><small>Dưới hoặc bằng ngưỡng cảnh báo</small></article>
    </section>
    <section class="workspace"><div class="toolbar"><label><span class="sr-only">Tìm nguyên liệu</span><input v-model="search" class="form-input" type="search" placeholder="Tìm tên hoặc mã nguyên liệu..." /></label><label><span class="sr-only">Trạng thái</span><select v-model="status" class="form-select"><option value="ACTIVE">Đang sử dụng</option><option value="INACTIVE">Ngừng sử dụng</option><option value="ALL">Tất cả</option></select></label><span class="result-count">{{ ingredients.length }} nguyên liệu</span></div>
      <div v-if="ingredientsNeedingStock.length" class="ingredient-attention-strip"><strong>{{ ingredientsNeedingStock.length }} nguyên liệu cần nhập thêm</strong><span>{{ ingredientsNeedingStock.slice(0, 3).map(item => item.name).join(', ') }}</span></div>
      <p v-if="error" class="error" role="alert">{{ error }}</p><div v-if="loading" class="state" role="status">Đang tải nguyên liệu...</div><div v-else-if="!ingredients.length" class="empty"><h2>Chưa có nguyên liệu</h2><p>Thêm nguyên liệu để sử dụng trong phiếu nhập, công thức và kiểm kê.</p><button class="btn btn-primary" @click="create">Thêm nguyên liệu đầu tiên</button></div>
      <template v-else><div class="table-wrap"><table><thead><tr><th>Nguyên liệu</th><th>Đơn vị chuẩn</th><th>Ngưỡng cảnh báo</th><th>Giá vốn hiện tại</th><th>Trạng thái dữ liệu</th><th>Thao tác</th></tr></thead><tbody><tr v-for="item in paginatedIngredients.items" :key="item.inventoryItemId"><td><strong>{{ item.name }}</strong><small>{{ item.inventoryCode }}</small></td><td>{{ unit(item.baseUnit) }}</td><td>{{ item.minimumQuantity }} {{ unit(item.baseUnit) }}</td><td>{{ Number(item.averageUnitCost) > 0 ? `${money(item.averageUnitCost)}/${unit(item.baseUnit)}` : 'Chưa có giá vốn' }}</td><td><span class="badge">{{ item.active === false ? 'Ngừng sử dụng' : Number(item.averageUnitCost) <= 0 ? 'Thiếu giá vốn' : Number(item.availableQuantity) <= Number(item.minimumQuantity) ? 'Cần nhập thêm' : 'Sẵn sàng' }}</span></td><td><div class="actions"><button class="btn btn-sm btn-primary" @click="router.push({ name: 'AdminGoodsReceipts' })">Nhập hàng</button><button class="btn btn-sm btn-outline" @click="edit(item)">Sửa</button></div></td></tr></tbody></table></div><div class="ingredient-card-list"><article v-for="item in paginatedIngredients.items" :key="item.inventoryItemId" class="ingredient-mobile-card"><header><div><strong>{{ item.name }}</strong><small>{{ item.inventoryCode }}</small></div><span class="badge">{{ item.active !== false ? 'Đang sử dụng' : 'Ngừng sử dụng' }}</span></header><dl><div><dt>Đơn vị</dt><dd>{{ unit(item.baseUnit) }}</dd></div><div><dt>Ngưỡng</dt><dd>{{ item.minimumQuantity }} {{ unit(item.baseUnit) }}</dd></div><div><dt>Giá vốn</dt><dd>{{ Number(item.averageUnitCost) > 0 ? `${money(item.averageUnitCost)}/${unit(item.baseUnit)}` : 'Chưa có giá vốn' }}</dd></div></dl><div class="actions"><button class="btn btn-primary" @click="router.push({ name: 'AdminGoodsReceipts' })">Nhập hàng</button><button class="btn btn-outline" @click="edit(item)">Sửa</button></div></article></div><footer class="pagination-footer"><span>{{ paginatedIngredients.from }}–{{ paginatedIngredients.to }} / {{ paginatedIngredients.totalItems }} nguyên liệu</span><nav aria-label="Phân trang nguyên liệu"><button type="button" :disabled="paginatedIngredients.page === 1" @click="ingredientPage--">‹</button><button v-for="page in paginatedIngredients.totalPages" :key="page" type="button" :aria-current="page === paginatedIngredients.page ? 'page' : undefined" :class="{ active: page === paginatedIngredients.page }" @click="ingredientPage = page">{{ page }}</button><button type="button" :disabled="paginatedIngredients.page === paginatedIngredients.totalPages" @click="ingredientPage++">›</button></nav></footer></template>
    </section>
    <div v-if="editing" class="backdrop" @mousedown.self="editing=null"><form class="dialog" role="dialog" aria-modal="true" aria-labelledby="ingredient-title" @submit.prevent="save"><header><div><small>NGUYÊN LIỆU</small><h2 id="ingredient-title">{{ editing.mode === 'create' ? 'Thêm nguyên liệu' : `Sửa ${editing.name}` }}</h2></div><button type="button" aria-label="Đóng" @click="editing=null">×</button></header><label>Mã nguyên liệu<input v-model="form.inventoryCode" class="form-input" maxlength="30" required /></label><label>Tên nguyên liệu<input v-model="form.name" class="form-input" maxlength="150" required /></label><label>Đơn vị chuẩn<select v-model="form.baseUnit" class="form-select" :disabled="editing.mode !== 'create'"><option value="G">g (gram)</option><option value="ML">ml (mililit)</option><option value="PIECE">cái</option></select></label><label>Ngưỡng cảnh báo<input v-model="form.minimumQuantity" class="form-input" type="number" min="0" step="0.0001" required /></label><label class="check"><input v-model="form.active" type="checkbox" /> Đang sử dụng</label><footer><button type="button" class="btn btn-outline" @click="editing=null">Hủy</button><button class="btn btn-primary" :disabled="saving">{{ saving ? 'Đang lưu...' : 'Lưu nguyên liệu' }}</button></footer></form></div>
  </main>
</template>

<style scoped>
.ingredients-page{display:grid;gap:20px;min-width:0}.command-card,.workspace,.ingredient-mobile-card{box-shadow:0 10px 28px rgba(15,23,42,.06)}.page-header,.toolbar,.actions,.dialog header,.dialog footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.page-header h1{margin:2px 0;font-size:30px}.page-header p{margin:0;color:var(--admin-muted)}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.1em;color:var(--admin-brand)!important;text-transform:uppercase}.command-rail{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:12px}.command-card{display:grid;gap:6px;min-height:112px;padding:18px;border:1px solid var(--admin-border);border-radius:var(--admin-panel-radius);background:var(--admin-surface);color:inherit;text-align:left}.command-card>span{color:var(--admin-muted);font-size:11px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.command-card strong{font-size:25px}.command-card small{color:var(--admin-muted)}button.command-card{cursor:pointer}.command-attention{border-color:color-mix(in srgb,var(--admin-brand) 35%,var(--admin-border));background:var(--admin-brand-soft)}.workspace{display:grid;gap:14px;padding:18px;border:1px solid var(--admin-border);border-radius:var(--admin-panel-radius);background:var(--admin-surface)}.toolbar{justify-content:flex-start}.toolbar label:first-child{flex:1;max-width:480px}.result-count{margin-left:auto;color:var(--admin-muted);font-size:12px}.ingredient-attention-strip{display:flex;gap:12px;padding:12px;border-radius:10px;background:var(--admin-warning-soft);color:var(--admin-warning)}.table-wrap{overflow-x:auto}table{width:100%;min-width:800px;border-collapse:collapse}th,td{padding:14px 10px;border-bottom:1px solid var(--admin-border);text-align:left}td:first-child{display:grid;gap:4px}.ingredient-card-list{display:none}.pagination-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:12px;border-top:1px solid var(--admin-border);color:var(--admin-muted);font-size:12px}.pagination-footer nav{display:flex;gap:6px}.pagination-footer button{min-width:40px;border:1px solid var(--admin-border);border-radius:10px;background:#fff}.pagination-footer button.active{border-color:var(--admin-brand);background:var(--admin-brand-soft);color:var(--admin-brand)}.state,.empty{padding:48px;text-align:center}.error{padding:12px;background:var(--admin-danger-soft);color:var(--admin-danger)}.backdrop{position:fixed;z-index:120;inset:0;display:grid;place-items:center;padding:20px;background:#1118}.dialog{display:grid;gap:14px;width:min(520px,100%);padding:22px;border-radius:18px;background:#fff;box-shadow:var(--admin-shadow-elevated)}.dialog label{display:grid;gap:6px}.dialog .check{display:flex}.dialog header h2{margin:3px 0}.dialog header button{width:44px;height:44px}.dialog footer{justify-content:flex-end}.ingredients-page :is(button,input,select):focus-visible{outline:3px solid var(--primary);outline-offset:2px}.ingredients-page :is(.btn,input,select){min-height:40px}@media(max-width:900px){.command-rail{grid-template-columns:1fr 1fr}.command-card:first-child{grid-column:1/-1}.table-wrap{display:none}.ingredient-card-list{display:grid;gap:10px}.ingredient-mobile-card{display:grid;gap:12px;padding:16px;border:1px solid var(--admin-border);border-radius:12px}.ingredient-mobile-card header{display:flex;justify-content:space-between;gap:12px}.ingredient-mobile-card header div{display:grid;gap:3px}.ingredient-mobile-card dl{display:grid;gap:7px;margin:0}.ingredient-mobile-card dl div{display:flex;justify-content:space-between;gap:12px}.ingredient-mobile-card dt{color:var(--admin-muted)}.ingredient-mobile-card dd{margin:0;font-weight:700}}@media(max-width:700px){.page-header{align-items:flex-start;flex-direction:column}.page-header .btn{width:100%}.command-rail{grid-template-columns:1fr}.command-card:first-child{grid-column:auto}.toolbar{align-items:stretch;flex-direction:column}.toolbar label:first-child{max-width:none}.result-count{margin-left:0}.ingredient-attention-strip{flex-direction:column}.ingredient-mobile-card .actions{display:grid;grid-template-columns:1fr 1fr}}@media(prefers-reduced-motion:reduce){.ingredients-page *{scroll-behavior:auto!important;animation-duration:.01ms!important}}
</style>
